                    let _ = send_text(&mut ws, "{\"type\":\"resync_required\"}".into());
                }
                let _ = ws.close(None);
                let _ = flush_by(&mut ws, Instant::now() + WRITE_TIMEOUT);
                return Ok(());
            }
        }
        match ws.read() {
            Ok(tungstenite::Message::Close(_)) => return Ok(()),
