        };
        let Ok(body) = serde_json::from_slice::<serde_json::Value>(&request.body) else {
            return self.refuse(request, 400, "bad_request", "the body is not JSON", false);
        };
        let field = |name: &str| {
            body.get(name)
                .and_then(|v| v.as_str())
                .unwrap_or("")
                .trim()
                .to_owned()
        };
        if field("spki_sha256") != identity.spki_sha256 {
